package org.adelheid.rs3types;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import org.jspecify.annotations.Nullable;

/**
 * Writes the LuaCATS of the game's constants from the CSVs in {@code generated/constants/}:
 * {@code generated/library/tables.lua}, the
 * tables {@code id}, {@code config} and {@code var} with a class for each of their namespaces, which every plugin's
 * code reads; and {@code constants/<Namespace>.lua}, the names of each namespace, which a project adds to its workspace
 * when it wants them, as they are many. A name file declares the same classes as tables.lua, which LuaLS merges, each
 * name a field of its own: in id typed by its ID, {@code ---@field HANS 0}, in config by its config type, and in var
 * as a {@code VarType} whose value type the description gives.
 */
final class ConstantsWriter {

	private static final Pattern COMMA = Pattern.compile(",");
	private static final Pattern IDENTIFIER = Pattern.compile("[A-Za-z_][A-Za-z0-9_]*");
	private static final Set<String> KEYWORDS = Set.of("and", "break", "do", "else", "elseif", "end", "false", "for",
			"function", "goto", "if", "in", "local", "nil", "not", "or", "repeat", "return", "then", "true", "until",
			"while");
	private static final String VARIABLE_TYPE = "VarType";

	private ConstantsWriter() {
	}

	/**
	 * Writes tables.lua into a library folder, and a name file a namespace into the constants folder, from the CSVs
	 * there; nothing where the constants folder has no tables.txt. A name file of a namespace the folder no longer has
	 * is deleted.
	 *
	 * @param configTypes the type of each config namespace's configs, {@code NPCType} for {@code NPC}
	 */
	static void write(Path constants, Path library, Map<String, String> configTypes) throws IOException {
		Map<String, List<String>> tables = Constants.tables(constants);
		if (tables.isEmpty()) {
			return;
		}
		List<String> ids = tables.getOrDefault("id", List.of());
		List<String> configs = tables.getOrDefault("config", List.of());
		List<String> variables = tables.getOrDefault("var", List.of());
		write(library.resolve("tables.lua"), tables(ids, configs, variables, configTypes));
		try (Stream<Path> files = Files.list(constants)) {
			for (Path file : files.filter(file -> file.toString().endsWith(".lua")).toList()) {
				Files.delete(file);
			}
		}
		for (String namespace : ids) {
			List<String> rows = Files.readAllLines(constants.resolve(namespace + ".csv"), StandardCharsets.UTF_8);
			write(constants.resolve(namespace + ".lua"), names(namespace, rows,
					configs.contains(namespace) ? configTypes.get(namespace) : null, variables.contains(namespace)));
		}
	}

	/** The tables id, config and var, each a class whose fields are its namespaces, each a class of its own. */
	static String tables(List<String> ids, List<String> configs, List<String> variables,
			Map<String, String> configTypes) {
		StringBuilder out = new StringBuilder("""
				---@meta
				-- Generated by rs3-api-types from the game client's constants, in generated/constants/; regenerate it
				-- with ./gradlew generate rather than editing it.

				---The game's IDs, by namespace and name: `id.NPC.HANS` is 0, and a name the namespace lacks reads -1. A
				---namespace's `FromID` gives the name of an ID. rs3-api-types' constants folder, added to a workspace's
				---libraries, names them all.
				""");
		table(out, "id", ids);
		for (String namespace : ids) {
			out.append("\n---The IDs of the ").append(namespace).append(" namespace, by name.\n")
					.append("---@class id.").append(namespace).append('\n')
					.append("---@field [string] integer\n")
					.append("---@field FromID fun(id: integer): string The name of an ID.\n");
		}
		out.append("""

				---The game's configs, by namespace and name: `config.NPC.HANS` is Hans's NPCType, and a name the
				---namespace lacks reads nil. A namespace's `FromID` gives the config of an ID.
				""");
		table(out, "config", configs);
		for (String namespace : configs) {
			String type = configTypes.getOrDefault(namespace, "any");
			out.append("\n---The ").append(namespace).append(" configs, by name.\n")
					.append("---@class config.").append(namespace).append('\n')
					.append("---@field [string] ").append(type).append('\n')
					.append("---@field FromID fun(id: integer): ").append(type).append(" The config of an ID.\n");
		}
		out.append("""

				---The game's variables, by domain and name: `var.VarPlayer.SOME_NAME.value` is a variable's value. A
				---domain's `FromID` gives the variable of an ID.
				""");
		table(out, "var", variables);
		for (String namespace : variables) {
			out.append("\n---The ").append(namespace).append(" variables, by name.\n")
					.append("---@class var.").append(namespace).append('\n')
					.append("---@field [string] ").append(VARIABLE_TYPE).append('\n')
					.append("---@field FromID fun(id: integer): ").append(VARIABLE_TYPE)
					.append(" The variable of an ID.\n");
		}
		return out.toString();
	}

	private static void table(StringBuilder out, String name, List<String> namespaces) {
		out.append("---@class ").append(name).append('\n');
		for (String namespace : namespaces) {
			out.append("---@field ").append(namespace).append(' ').append(name).append('.').append(namespace)
					.append('\n');
		}
		out.append(name).append(" = {}\n");
	}

	/**
	 * A namespace's names: in its id class, each typed by its ID; in its config class, if it has one, each typed by its
	 * config type; and in its var class, if it is a domain of variables, each a VarType.
	 *
	 * @param rows the namespace's CSV rows, {@code id,NAME}, a variable's going on with its value type, base variable
	 *     and bit mask
	 * @param configType the type of the namespace's configs; null for a namespace config does not have
	 */
	static String names(String namespace, List<String> rows, @Nullable String configType, boolean variables) {
		List<List<String>> cells = new ArrayList<>();
		for (String row : rows) {
			if (!row.isBlank()) {
				cells.add(COMMA.splitAsStream(row).toList());
			}
		}
		StringBuilder out = new StringBuilder("---@meta\n")
				.append("-- Generated by rs3-api-types from the game client's names, in generated/constants/")
				.append(namespace)
				.append(".csv; regenerate it\n")
				.append("-- with ./gradlew generate rather than editing it.\n\n")
				.append("---@class id.").append(namespace).append('\n');
		for (List<String> row : cells) {
			out.append("---@field ").append(key(row.get(1))).append(' ').append(row.get(0)).append('\n');
		}
		if (configType != null) {
			out.append("\n---@class config.").append(namespace).append('\n');
			for (List<String> row : cells) {
				out.append("---@field ").append(key(row.get(1))).append(' ').append(configType).append('\n');
			}
		}
		if (variables) {
			out.append("\n---@class var.").append(namespace).append('\n');
			for (List<String> row : cells) {
				out.append("---@field ").append(key(row.get(1))).append(' ').append(VARIABLE_TYPE);
				if (row.size() >= 3) {
					out.append(" Its values are ").append(row.get(2));
					if (row.size() >= 5) {
						out.append(", in the bits ").append(row.get(4)).append(" of ").append(namespace).append(' ')
								.append(row.get(3));
					}
					out.append('.');
				}
				out.append('\n');
			}
		}
		return out.toString();
	}

	/** A field's name, or a name that is no Lua identifier as an index, ["NAME"]. */
	private static String key(String name) {
		return IDENTIFIER.matcher(name).matches() && !KEYWORDS.contains(name) ? name : "[\"" + name + "\"]";
	}

	private static void write(Path file, String text) throws IOException {
		Files.createDirectories(file.getParent());
		Files.writeString(file, text, StandardCharsets.UTF_8);
	}
}
